BEGIN;

INSERT INTO public.questions
  (subject_id, category_id, source_ref, question_text, code, options,
   correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, v.source_ref, v.question_text, v.code, v.options::jsonb,
       v.correct_index, v.correct_indices::jsonb, v.question_type, '', v.explanation_data::jsonb, 1
FROM public.subjects s
JOIN public.categories c ON c.subject_id = s.id
JOIN (VALUES

  ('stats20-q01', '確率過程とシミュレーション',
   '毎日の最高気温を並べたグラフのように、時間の流れに沿ったデータの変化を扱うのが時系列解析だった。確率過程はこれと近い題材を扱うが、「次の値」の決まり方にある違いがある。確率過程の説明として最も適切なのはどれ？',
   NULL::text,
   '["時間とともに変化し、次の値が確率的に決まっていく現象を数式で扱う枠組み", "時間とともに変化しても、次の値は必ず1通りに正確に決まる現象を扱う枠組み", "時間の流れとは関係なく、複数の変数どうしの関係だけを扱う枠組み", "過去の値を完全に無視して、毎回まったくのでたらめに値を決める枠組み"]',
   0, '[0]', 'single',
   '{"asked": "確率過程という言葉が、時間とともに変わる現象のどんな側面をモデル化する枠組みなのか。", "point": "時間とともに動き、次の値がサイコロのように確率で決まる現象を扱うのが確率過程。", "kid": "時系列解析は、時間順に並んだデータをただ観察して分析する話だった。確率過程は一歩進んで、『次にどんな値になるかは、サイコロを振るみたいに確率で決まる』という前提で、その変化そのものを数式でモデル化する分野。", "eg": "すごろくを思い浮かべる。コマの位置は毎ターン、サイコロの出目に応じて確率的に変わっていく。この『時間(ターン)とともに、確率で次が決まっていく』動き方そのものが確率過程のイメージ。", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\">\n<text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">今の状態から、次はどこへ転ぶか確率で決まる</text>\n<circle cx=\"55\" cy=\"75\" r=\"7\" fill=\"#3b82f6\"/>\n<text x=\"55\" y=\"100\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">今の状態</text>\n<line x1=\"64\" y1=\"70\" x2=\"230\" y2=\"35\" stroke=\"#60a5fa\" stroke-width=\"1.3\" stroke-dasharray=\"3 2\"/>\n<line x1=\"64\" y1=\"75\" x2=\"230\" y2=\"75\" stroke=\"#60a5fa\" stroke-width=\"1.3\" stroke-dasharray=\"3 2\"/>\n<line x1=\"64\" y1=\"80\" x2=\"230\" y2=\"112\" stroke=\"#60a5fa\" stroke-width=\"1.3\" stroke-dasharray=\"3 2\"/>\n<circle cx=\"238\" cy=\"35\" r=\"6\" fill=\"#2a2f3f\" stroke=\"#60a5fa\"/>\n<circle cx=\"238\" cy=\"75\" r=\"6\" fill=\"#2a2f3f\" stroke=\"#60a5fa\"/>\n<circle cx=\"238\" cy=\"112\" r=\"6\" fill=\"#2a2f3f\" stroke=\"#60a5fa\"/>\n<text x=\"256\" y=\"38\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"start\">50%</text>\n<text x=\"256\" y=\"78\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"start\">30%</text>\n<text x=\"256\" y=\"115\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"start\">20%</text>\n<text x=\"170\" y=\"132\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">次の値は1つに決まらず、確率で分かれていく</text>\n</svg>", "terms": [["確率過程", "時間とともに変化する確率的な現象を扱う数学の枠組み"], ["時系列解析", "時間順に並んだデータの変化を分析する、既に学んだ手法"]], "think": "なぜ『確率的に決まる』という点が時系列解析との違いになるのかがカギ。時系列解析は、すでに手元にある気温や株価の記録を分析する立場で、次の値がどう生まれるかの仕組みまでは踏み込まない。確率過程は逆に、『次の値はどんなルールで、どれくらいの確率で決まるのか』という生成のルールそのものを数式で表す。同じ『時間とともに変わるデータ』を扱っていても、記録を観察する立場か、生まれ方のルールを作る立場かという違いがある。", "vs": "時系列解析は、観測されたデータの並びをそのまま分析する学問。確率過程は、そのデータがどんな確率のルールで生まれたかという発生の仕組みそのものをモデル化する数学。似ているが見ている対象の階層が違う。", "why_asked": "このあとに出てくるマルコフ連鎖やポアソン過程は、どちらも確率過程の具体的な例にあたる。まず確率過程という大きな枠組みを知らないと、それぞれがバラバラの概念に見えてしまう。", "usecase": "天気の移り変わり、株価の変動、機械の故障発生のタイミングなど、『時間とともに変わり、次がランダムに決まる』現象は、すべて確率過程としてモデル化される。", "opt": ["正解。確率過程は、時間とともに変化し、次の値がサイコロのように確率のルールで決まっていく現象を扱う数学の枠組み。", "次の値が必ず1通りに正確に決まるなら、確率は関係ない。確率過程が扱うのは、次の値が確率的にしか決まらない現象。", "複数の変数どうしの関係だけを扱うのは多変量解析に近い考え方。確率過程は時間の流れに沿った変化を扱う点が中心になる。", "過去をまったく無視した完全にでたらめな値の並びは、確率のルールにすら従っていない。確率過程は『確率のルールに従って』次が決まる点が要になる。"]}'),

  ('stats20-q02', '確率過程とシミュレーション',
   'すごろくでコマが今どのマスにいるかだけ分かれば、次にどのマスへ進むかの確率が決まり、そこまでどんな道順でそのマスに来たかは関係ない。このような「次の状態が直前の状態だけで決まり、それより前の履歴によらない」という性質を何と呼ぶ？',
   NULL::text,
   '["マルコフ性（直前の状態だけで次が決まり、それより前の履歴は関係ない性質）", "定常性（時間が経過しても、平均や分散などの統計的な性質が変わらないという性質）", "独立性（ある出来事の結果が、他の出来事の結果とはまったく無関係になる性質）", "再現性（まったく同じ条件で実験すれば、毎回同じ結果になるという性質）"]',
   0, '[0]', 'single',
   '{"asked": "『直前の状態だけで次が決まり、それより前の履歴は関係ない』という性質の名前。", "point": "『今の状態』だけ見れば十分で、そこに至るまでの過去の経路は次を決めるのに使わない、が決め手。", "kid": "マルコフ性は、『今どこにいるか』さえ分かれば次の動きの確率が決まり、『どうやってそこに来たか』という昔の経緯はいっさい関係ない、という性質。", "eg": "すごろくでいうと、今3マス目にいるなら、次どこへ進むかはサイコロの出目だけで決まる。1マス目からスタートしたか、途中で戻ってきたかという通ってきた道順は、次の一手にはまったく影響しない。", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\">\n<text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">今のマスだけ見る。通ってきた道は使わない</text>\n<path d=\"M48,50 Q88,28 108,50\" fill=\"none\" stroke=\"#8892a4\" stroke-width=\"1\" stroke-dasharray=\"2 2\" opacity=\"0.6\"/>\n<text x=\"78\" y=\"26\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\" opacity=\"0.7\">通ってきた道(関係ない)</text>\n<rect x=\"30\" y=\"55\" width=\"36\" height=\"30\" fill=\"#2a2f3f\" opacity=\"0.5\"/>\n<rect x=\"70\" y=\"55\" width=\"36\" height=\"30\" fill=\"#2a2f3f\" opacity=\"0.5\"/>\n<rect x=\"110\" y=\"55\" width=\"36\" height=\"30\" fill=\"#3b82f6\"/>\n<rect x=\"150\" y=\"55\" width=\"36\" height=\"30\" fill=\"#60a5fa\" opacity=\"0.35\"/>\n<rect x=\"190\" y=\"55\" width=\"36\" height=\"30\" fill=\"#60a5fa\" opacity=\"0.35\"/>\n<text x=\"48\" y=\"74\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">1</text>\n<text x=\"88\" y=\"74\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">2</text>\n<text x=\"128\" y=\"74\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"700\">今3</text>\n<text x=\"168\" y=\"74\" fill=\"#e8eaf0\" font-size=\"9\" text-anchor=\"middle\">4</text>\n<text x=\"208\" y=\"74\" fill=\"#e8eaf0\" font-size=\"9\" text-anchor=\"middle\">5</text>\n<text x=\"170\" y=\"104\" fill=\"#60a5fa\" font-size=\"9\" text-anchor=\"middle\">次は4か5へ、今3マス目にいることだけで確率が決まる</text>\n<text x=\"170\" y=\"122\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">1・2マス目をどう通ってきたかは関係ない</text>\n</svg>", "terms": [["マルコフ性", "直前の状態だけで次が決まり、それより前の経過は関係ないという性質"], ["確率過程", "時間とともに変化する確率的な現象を扱う枠組み。前問で学んだ言葉"]], "think": "なぜ『直前の状態だけ』で十分と考えるのかがカギ。もし本当に次の動きを決めるのにこれまでの全履歴が必要だとしたら、履歴が長くなるほど考慮すべきパターンが爆発的に増え、計算がとても大変になる。マルコフ性は『今の状態に、それまでの経緯の影響はすべて集約されている』とみなすことで、直前の状態だけを覚えておけば十分、という割り切りをする。この割り切りのおかげで、複雑に見える現象も簡単な確率のルールで扱えるようになる。", "vs": "独立性は『2つの出来事がまったく無関係』という強い仮定。マルコフ性は『直前の状態にだけは依存してよい、それより前とは無関係』という、独立性よりゆるい仮定。", "why_asked": "このあとの遷移確率や天気の推移モデルは、すべてこのマルコフ性を前提にして作られている。マルコフ性を理解していないと、『なぜ過去の履歴を全部記録しなくていいのか』が分からなくなる。", "usecase": "天気予報の簡易モデル、Webページの遷移予測、文章の次の単語を予測する言語モデルの一部など、『直前の状態さえ分かれば十分』と割り切ることで計算を簡単にする場面で使われる。", "opt": ["正解。直前の状態だけで次が決まり、それより前の経緯には左右されないという性質がマルコフ性。", "定常性は、時間が経っても平均や分散などの統計的な性質が変わらないという別の性質。今回問われている『履歴によらない』という話とは別物。", "独立性は2つの出来事がまったく無関係であるという性質。マルコフ性は直前の状態には依存してよいので、独立性よりゆるい仮定になる。", "再現性は同じ条件なら同じ結果になるという性質で、実験の再現性などで使う言葉。確率的に次が決まるマルコフ連鎖の性質とは別の話。"]}'),

  ('stats20-q03', '確率過程とシミュレーション',
   'マルコフ連鎖で、「晴れの次の日が晴れになる確率は70%、雨になる確率は30%」のように、ある状態から別の状態へ移る確率のことを何と呼ぶ？',
   NULL::text,
   '["遷移確率（ある状態から別の状態へ移る確率）", "事前確率（証拠を見る前の時点での見込みの確率）", "尤度（ある原因を仮定したときに、その結果がどれくらい出やすいかを表す確率）", "条件付き確率（ある条件が分かったうえでの確率全般を指す、より広い呼び方）"]',
   0, '[0]', 'single',
   '{"asked": "マルコフ連鎖で、状態から状態への移り変わりを表す確率の名前。", "point": "遷移確率は『今の状態→次の状態』という矢印1本ずつに付いている確率の値。", "kid": "遷移確率は、『今晴れなら、次は晴れが70%、雨が30%』というように、今の状態から次の状態へどれくらいの確率で移るかを表す数字。", "eg": "鉄道の乗り換え図を思い浮かべる。駅Aから駅Bへ乗り換える人がどれくらいの割合いるか、というように、状態と状態を結ぶ矢印1本ごとに数字が振られているイメージ。", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\">\n<text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">状態から状態への矢印についた確率</text>\n<circle cx=\"95\" cy=\"80\" r=\"30\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/>\n<text x=\"95\" y=\"84\" fill=\"#e8eaf0\" font-size=\"10.5\" text-anchor=\"middle\" font-weight=\"600\">晴れ</text>\n<circle cx=\"245\" cy=\"80\" r=\"30\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/>\n<text x=\"245\" y=\"84\" fill=\"#e8eaf0\" font-size=\"10.5\" text-anchor=\"middle\" font-weight=\"600\">雨</text>\n<line x1=\"125\" y1=\"73\" x2=\"215\" y2=\"73\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/>\n<polygon points=\"215,73 207,69 207,77\" fill=\"#3b82f6\"/>\n<text x=\"170\" y=\"65\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">30%</text>\n<line x1=\"215\" y1=\"89\" x2=\"125\" y2=\"89\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/>\n<polygon points=\"125,89 133,85 133,93\" fill=\"#3b82f6\"/>\n<text x=\"170\" y=\"105\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">40%</text>\n<text x=\"170\" y=\"128\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">この矢印1本ごとの確率が遷移確率</text>\n</svg>", "terms": [["遷移確率", "マルコフ連鎖で、ある状態から別の状態へ移る確率"], ["状態", "マルコフ連鎖が今どこにいるかを表す区分。晴れ・雨のような分類"]], "think": "なぜ状態ごとに遷移確率をすべて書き出す必要があるのかがカギ。マルコフ性により、次の状態は今の状態だけで決まる。ということは、『晴れの次にどうなるか』『雨の次にどうなるか』というように、それぞれの状態ごとに次の状態への確率をあらかじめ決めておけば、そこから先の動きはすべて計算できる。この『状態ごとの次への確率』の一覧こそが遷移確率であり、マルコフ連鎖の中身そのものにあたる。", "vs": "事前確率・尤度はベイズ統計の言葉で、証拠を見る前後の見込みを扱う。遷移確率はマルコフ連鎖の言葉で、状態から状態への移り変わりそのものを扱う。似た『確率』でも登場する場面が違う。", "why_asked": "マルコフ連鎖を実際に計算するには、それぞれの状態からそれぞれの状態へ移る確率、つまり遷移確率の数字が必要になる。マルコフ性(直前の状態だけで決まる)という性質と、遷移確率(その移り方の具体的な数字)はセットで理解する。", "usecase": "天気の推移モデル、Webページ間のクリック遷移、ゲームのすごろくの目の出方など、『Aの次にBになる確率』を具体的な数字で表すときに使う。", "opt": ["正解。ある状態から別の状態へ移る確率のことを遷移確率と呼ぶ。晴れの次に晴れになる確率70%はその一例。", "事前確率は証拠を見る前の見込みを指すベイズ統計の言葉。状態から状態への移り変わりを表す遷移確率とは別の場面で使う。", "尤度は原因を仮定したときの結果の出やすさを表すベイズ統計の言葉。状態の移り変わりそのものを表す遷移確率とは別物になる。", "条件付き確率という呼び方自体は間違いではないが、それは『ある条件のもとでの確率』全般を指す広い言葉。状態から状態への移り変わりを特に指すときは遷移確率と呼ぶ。"]}'),

  ('stats20-q04', '確率過程とシミュレーション',
   'マルコフ連鎖にあてはまる身近な例として、最も適切なのはどれ？',
   NULL::text,
   '["Webサイトで、今見ているページによって、次に見られやすいページの確率が変わる、ページ間の移動", "サイコロを何度振っても、毎回の出目が前の出目とはまったく無関係に決まる、独立な試行の繰り返し", "何年分もの天気の記録をすべて細かく保存しておき、その全履歴をもとに来週の天気を予測する統計モデル", "商品の売上の変化を、曜日や季節ごとの周期的なパターンに沿ってそのまま予測する時系列のモデル"]',
   0, '[0]', 'single',
   '{"asked": "マルコフ性(直前の状態だけで次が決まる)に当てはまる現象は、実際にどんな場面か。", "point": "『今の状態だけで次の確率が決まる』に当てはまる現象がマルコフ連鎖の例。全履歴を使う予測や、前と無関係な独立試行は当てはまらない。", "kid": "マルコフ連鎖に当てはまるのは、『今の状態』さえ分かれば次の確率が決まり、それより前の経緯は使わない現象。天気の推移やWebページの遷移が定番の例。", "eg": "Webページ間のリンクをたどる動きが分かりやすい。このページを見た人は次にこのページを見やすい、というように、今いるページによって次に進みやすい先が変わる。これがそのままマルコフ連鎖の例になる。", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\">\n<text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">Webページの遷移もマルコフ連鎖の例</text>\n<circle cx=\"60\" cy=\"75\" r=\"26\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/>\n<text x=\"60\" y=\"79\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">トップ</text>\n<circle cx=\"180\" cy=\"45\" r=\"26\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/>\n<text x=\"180\" y=\"49\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">商品一覧</text>\n<circle cx=\"280\" cy=\"100\" r=\"26\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/>\n<text x=\"280\" y=\"104\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">購入</text>\n<line x1=\"82\" y1=\"63\" x2=\"158\" y2=\"52\" stroke=\"#3b82f6\" stroke-width=\"1.3\"/>\n<text x=\"120\" y=\"48\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">60%</text>\n<line x1=\"200\" y1=\"63\" x2=\"258\" y2=\"83\" stroke=\"#3b82f6\" stroke-width=\"1.3\"/>\n<text x=\"235\" y=\"65\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">25%</text>\n<line x1=\"82\" y1=\"88\" x2=\"256\" y2=\"105\" stroke=\"#8892a4\" stroke-width=\"1\" stroke-dasharray=\"2 2\"/>\n<text x=\"170\" y=\"132\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">今いるページで、次に進みやすい先が変わる</text>\n</svg>", "terms": [["マルコフ連鎖", "直前の状態だけで次が確率的に決まっていく現象の連なり"], ["独立な試行", "前の結果が次の結果にまったく影響しない試行。マルコフ連鎖とは違う考え方"]], "think": "なぜWebページの遷移がマルコフ連鎖に当てはまるのかがカギ。あるページを見ている人が次にどのページへ移動するかは、そのページの内容やリンク構成、つまり『今どのページにいるか』でおおよそ決まる。そこに至るまでにどんな順番でページを巡ってきたかは、次の移動先の確率にはほとんど影響しない。この『今の状態だけで次が決まる』という構造が、そのままマルコフ連鎖の定義に当てはまる。一方、独立な試行はそもそも『今の状態』という概念を使わない点でさらに単純であり、全履歴を使う予測は逆にマルコフ性の割り切りをしていない点で、どちらもマルコフ連鎖の例としては当てはまらない。", "vs": "独立な試行の繰り返し(サイコロなど)は、直前の状態にすら依存しないので、マルコフ連鎖よりさらに単純な特殊ケース。全履歴を使う予測は逆に、マルコフ性(直前だけで十分)という割り切りをしていない。", "why_asked": "マルコフ性という定義だけを覚えても、実際にどんな現象がそれに当てはまるのかが分からないと、このあとのポアソン過程との区別もつきにくくなる。具体例で『今の状態だけで決まる』という感覚をつかんでおく。", "usecase": "検索エンジンのページランク計算、Webサイトの導線分析、簡易な天気予測モデルなど、『今の状態から次への移り変わり』を確率で扱いたい場面で、マルコフ連鎖の考え方が使われる。", "opt": ["正解。今見ているページによって次に見られやすいページの確率が変わるのは、『今の状態だけで次が決まる』というマルコフ連鎖の典型例。", "サイコロの独立な試行は、前の出目にすら影響されない。マルコフ連鎖は『直前の状態には依存する』ので、独立な試行はさらに単純な別のケースになる。", "何年分もの全履歴を使う予測は、『直前の状態だけで十分』というマルコフ性の割り切りをしていない。全履歴を使う時点でマルコフ連鎖の考え方とは異なる。", "曜日や季節の周期パターンに沿った予測は、時系列解析でよく使われる考え方であり、状態から状態への移り変わりを扱うマルコフ連鎖とは着眼点が異なる。"]}'),

  ('stats20-q05', '確率過程とシミュレーション',
   '1時間に平均3件のペースでランダムに電話がかかってくるコールセンターのように、「一定の割合でランダムに出来事が起きる」現象を、時間の流れに沿ってモデル化したものを何と呼ぶ？',
   NULL::text,
   '["ポアソン過程（一定の割合でランダムに出来事が起きる現象を、時間の流れに沿って表すモデル）", "マルコフ連鎖（直前の状態だけで次の状態が確率的に決まっていく現象のつながりを表すモデル）", "二項分布（結果が2択になる試行をn回繰り返したときの、当たりの回数がどう散らばるかを表す分布）", "正規分布（平均の近くにデータが集まり、離れるほど少なくなる左右対称の山型をした分布）"]',
   0, '[0]', 'single',
   '{"asked": "『1時間に平均○件』のように一定のペースでランダムに起きる出来事を、時間の流れに沿って表すモデルの名前。", "point": "『1時間に平均○件』のように、起きるペースは一定だが、いつ起きるかはランダム、という現象を時間の流れごと表すのがポアソン過程。", "kid": "『1時間に平均3件』のように起こりやすさの目安(平均)だけ分かっている出来事が、ある区切りの中で実際に何回起きるかを表す分布をポアソン分布と呼ぶ。ポアソン過程は、この『1時間に何回』という区切りを外して、時間をずっと連続的に流しながら、出来事がいつ起きるかをまるごとモデル化したもの。", "eg": "レジに並ぶ人の間隔を思い浮かべる。何時何分に何人来るかは決まっていないが、1時間あたりで見ると来る人数のペースはだいたい一定。そのランダムな来店の様子をそのまま数式で表したのがポアソン過程。", "viz": "<svg viewBox=\"0 0 340 130\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\">\n<text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">ランダムなタイミングで起きる出来事</text>\n<line x1=\"30\" y1=\"70\" x2=\"310\" y2=\"70\" stroke=\"#2a2f3f\" stroke-width=\"1.3\"/>\n<line x1=\"55\" y1=\"55\" x2=\"55\" y2=\"85\" stroke=\"#3b82f6\" stroke-width=\"2\"/>\n<line x1=\"90\" y1=\"55\" x2=\"90\" y2=\"85\" stroke=\"#3b82f6\" stroke-width=\"2\"/>\n<line x1=\"102\" y1=\"55\" x2=\"102\" y2=\"85\" stroke=\"#3b82f6\" stroke-width=\"2\"/>\n<line x1=\"160\" y1=\"55\" x2=\"160\" y2=\"85\" stroke=\"#3b82f6\" stroke-width=\"2\"/>\n<line x1=\"230\" y1=\"55\" x2=\"230\" y2=\"85\" stroke=\"#3b82f6\" stroke-width=\"2\"/>\n<line x1=\"245\" y1=\"55\" x2=\"245\" y2=\"85\" stroke=\"#3b82f6\" stroke-width=\"2\"/>\n<line x1=\"290\" y1=\"55\" x2=\"290\" y2=\"85\" stroke=\"#3b82f6\" stroke-width=\"2\"/>\n<text x=\"170\" y=\"102\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">間隔はバラバラでも、平均のペースは一定</text>\n<text x=\"170\" y=\"118\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">これを時間の流れごとモデル化したのがポアソン過程</text>\n</svg>", "terms": [["ポアソン過程", "一定の割合でランダムに出来事が起きる現象を、時間の流れに沿って表すモデル"], ["ポアソン分布", "一定時間内に起きる出来事の回数が、平均何回か分かっているときに、実際に何回起きるかを表す確率分布"]], "think": "なぜポアソン分布を『拡張』したものがポアソン過程なのかがカギ。ポアソン分布は『1時間』のように区切った1つの窓の中で、出来事が何回起きるかだけを見る。ポアソン過程は、この窓を1時間、10分、1分、1秒とどんどん細かくしていっても、『一定の割合でランダムに起きる』という性質が保たれ続けるように、時間の流れ全体をひとつなぎでモデル化したもの。区切った窓の中の回数(ポアソン分布)と、時間の流れ全体でのランダムな発生(ポアソン過程)は、同じ『一定の割合でランダムに起きる』という考え方の、切り取り方の違いにあたる。", "vs": "マルコフ連鎖は『今どの状態にいるか』という区分(晴れ・雨など)の移り変わりを扱う。ポアソン過程は状態の区分ではなく、『出来事がいつ起きるか』という発生のタイミングそのものを扱う。着眼点が違う。", "why_asked": "『一定のペースでランダムに起きる出来事』は電話・故障・事故など日常のいたるところにある。これをきちんとモデル化する言葉(ポアソン過程)を知らないと、『平均は分かっているのに、いつ起きるか予測できない』現象をどう扱えばいいか分からなくなる。", "usecase": "コールセンターへの着信、Webサーバーへのアクセス、交差点での事故の発生など、『平均のペースは分かっているが、いつ起きるかはランダム』な現象の待ち時間や混雑具合を計算するときに使う。", "opt": ["正解。一定の割合でランダムに出来事が起きる現象を、時間の流れに沿ってモデル化したものがポアソン過程。", "マルコフ連鎖は『今どの状態にいるか』の移り変わりを扱う枠組み。出来事がいつ起きるかそのものを扱うポアソン過程とは着眼点が違う。", "二項分布は結果が2択の試行をn回繰り返したときの当たりの回数の分布。時間の流れに沿った出来事の発生を扱うポアソン過程とは別物。", "正規分布は平均の近くにデータが集まる左右対称の山型の分布。ランダムな出来事の発生タイミングを扱うポアソン過程とは別の分布になる。"]}'),

  ('stats20-q06', '確率過程とシミュレーション',
   'ポアソン過程がうまく当てはまる現象として、最も適切なのはどれ？',
   NULL::text,
   '["銀行の窓口に、平均して10分に1人のペースで、ランダムなタイミングで客が訪れる", "毎朝ちょうど8時00分に、始発電車がきっちり1本だけ決まった時刻に発車していく", "工場の生産ラインで、決められた手順どおりに、毎回同じ間隔で部品が流れてくる", "テストの点数が、平均60点を中心にして左右対称の山型にきれいに散らばる"]',
   0, '[0]', 'single',
   '{"asked": "ポアソン過程が当てはまる現象と、当てはまらない現象の見分け方。", "point": "『平均のペースは分かるが、次がいつ来るかはランダム』ならポアソン過程。時刻表のように間隔が固定されている現象には当てはまらない。", "kid": "ポアソン過程が当てはまるのは、『平均のペースは決まっているけど、次がいつ来るかは毎回ランダム』な現象。逆に、時刻表どおりに来る電車のような『毎回きっちり同じ間隔』の現象には当てはまらない。", "eg": "窓口に並ぶお客さんは、10分に1人来るといっても、実際には3分後に来たり、次は20分空いたりとバラバラ。これがポアソン過程。始発電車のように毎日ぴったり8時発車、というのはランダムさが無いのでポアソン過程には当てはまらない。", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\">\n<text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">ランダムな間隔 vs 決まった間隔</text>\n<text x=\"40\" y=\"34\" fill=\"#60a5fa\" font-size=\"9\" text-anchor=\"start\">窓口の来客</text>\n<line x1=\"30\" y1=\"55\" x2=\"310\" y2=\"55\" stroke=\"#2a2f3f\" stroke-width=\"1.3\"/>\n<line x1=\"50\" y1=\"45\" x2=\"50\" y2=\"65\" stroke=\"#3b82f6\" stroke-width=\"2\"/>\n<line x1=\"80\" y1=\"45\" x2=\"80\" y2=\"65\" stroke=\"#3b82f6\" stroke-width=\"2\"/>\n<line x1=\"95\" y1=\"45\" x2=\"95\" y2=\"65\" stroke=\"#3b82f6\" stroke-width=\"2\"/>\n<line x1=\"170\" y1=\"45\" x2=\"170\" y2=\"65\" stroke=\"#3b82f6\" stroke-width=\"2\"/>\n<line x1=\"260\" y1=\"45\" x2=\"260\" y2=\"65\" stroke=\"#3b82f6\" stroke-width=\"2\"/>\n<text x=\"286\" y=\"70\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">ランダム</text>\n<text x=\"40\" y=\"96\" fill=\"#60a5fa\" font-size=\"9\" text-anchor=\"start\">始発電車</text>\n<line x1=\"30\" y1=\"115\" x2=\"310\" y2=\"115\" stroke=\"#2a2f3f\" stroke-width=\"1.3\"/>\n<line x1=\"50\" y1=\"105\" x2=\"50\" y2=\"125\" stroke=\"#c9a04a\" stroke-width=\"2\"/>\n<line x1=\"110\" y1=\"105\" x2=\"110\" y2=\"125\" stroke=\"#c9a04a\" stroke-width=\"2\"/>\n<line x1=\"170\" y1=\"105\" x2=\"170\" y2=\"125\" stroke=\"#c9a04a\" stroke-width=\"2\"/>\n<line x1=\"230\" y1=\"105\" x2=\"230\" y2=\"125\" stroke=\"#c9a04a\" stroke-width=\"2\"/>\n<line x1=\"290\" y1=\"105\" x2=\"290\" y2=\"125\" stroke=\"#c9a04a\" stroke-width=\"2\"/>\n<text x=\"286\" y=\"130\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">同じ間隔</text>\n</svg>", "terms": [["ポアソン過程", "一定の割合でランダムに出来事が起きる現象を時間の流れに沿って表すモデル"], ["到着間隔", "出来事と出来事の間の時間の長さ。ポアソン過程ではこの間隔もランダムに変わる"]], "think": "なぜ規則正しい現象にはポアソン過程が当てはまらないのかがカギ。ポアソン過程の土台にあるのは『出来事どうしが互いに無関係で、いつ起きるかはランダム』という前提。始発電車や生産ラインの部品のように、次がいつ来るかが最初から決まっている現象は、この『ランダムに起きる』という前提そのものを満たしていない。窓口の来客のように、平均のペースはあっても1件1件の到着タイミングが互いに無関係でランダムな現象こそが、ポアソン過程で扱う対象になる。", "vs": "電車の時刻表や工場の一定間隔の生産ラインのように、間隔そのものが決まっている現象は、ランダムさが無いのでポアソン過程には当てはまらない。ポアソン過程が当てはまるのは、あくまで『間隔自体もランダムに変わる』現象。", "why_asked": "ポアソン過程は『ランダムに起きる』という点が本質。この条件を確認せずに、時間的に規則正しく起きる現象にまでポアソン過程をあてはめてしまうと、モデルと実際の現象がかみ合わなくなる。", "usecase": "コールセンターの着信数の予測、レジの待ち行列の混雑具合の計算、機械の故障が起きるまでの時間の見積もりなど、『平均のペースは分かるがタイミングはランダム』な現象の分析で使われる。", "opt": ["正解。窓口に平均10分に1人、ランダムなタイミングで客が訪れるのは、『平均のペースは決まっているが次はいつ来るか分からない』というポアソン過程の当てはまり方の典型例。", "始発電車が毎日ちょうど8時に決まった時刻に発車するのは、間隔が固定された規則正しい現象。ランダムさが無いのでポアソン過程には当てはまらない。", "生産ラインで毎回同じ間隔で部品が流れてくるのも、間隔が固定された規則正しい現象。ランダムに起きる出来事を扱うポアソン過程とは異なる。", "テストの点数が平均を中心に左右対称に散らばるのは正規分布の話。出来事が時間の中でいつ起きるかを扱うポアソン過程とは別の話題になる。"]}'),

  ('stats20-q07', '確率過程とシミュレーション',
   'サイコロを100万回コンピュータでシミュレーションして、出た目の合計がある範囲に収まる確率を、実際に数えて見積もる。このように、数式で正確に解くのが難しい問題を、大量の乱数を使ったシミュレーションで近似的に解く方法を何と呼ぶ？',
   NULL::text,
   '["モンテカルロ法（乱数を使った大量のシミュレーションで、近似的に答えを求める方法）", "最小二乗法（誤差の2乗の合計が最小になるように、直線などの式を決める方法）", "交差検証（データの分け方を何通りも変えて、モデルの性能を複数回確かめる方法）", "ベイズ更新（新しい証拠が入るたびに、前の答えを次の出発点として確率を計算し直すこと）"]',
   0, '[0]', 'single',
   '{"asked": "数式で正確に解くのが難しい問題を、乱数を使ったシミュレーションで近似的に解く方法の名前。", "point": "数式で正確に解けない問題を、乱数で大量に試してみて、その結果から答えを見積もるのがモンテカルロ法。", "kid": "モンテカルロ法は、数式を解くのが難しい問題でも、コンピュータでランダムな試行をものすごい回数繰り返して、その結果を数えることで、答えに近い値を見積もる方法。", "eg": "『サイコロを100万回振ってみたら、こういう結果になった』と実際にやってみて答えを見積もるようなもの。数式で計算しきれない複雑な問題でも、実際に(コンピュータの中で)何度も試してみれば、答えのだいたいの見当がつく。", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\">\n<text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">乱数を大量に試すほど、答えに近づく</text>\n<line x1=\"30\" y1=\"115\" x2=\"310\" y2=\"115\" stroke=\"#2a2f3f\" stroke-width=\"1.3\"/>\n<line x1=\"30\" y1=\"30\" x2=\"30\" y2=\"115\" stroke=\"#2a2f3f\" stroke-width=\"1.3\"/>\n<line x1=\"30\" y1=\"55\" x2=\"310\" y2=\"55\" stroke=\"#6ab08d\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n<text x=\"300\" y=\"48\" fill=\"#6ab08d\" font-size=\"8.5\" text-anchor=\"end\">本当の答え</text>\n<path d=\"M40,35 L70,95 L100,42 L130,88 L160,50 L190,66 L220,58 L250,52 L280,56 L300,54\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/>\n<text x=\"45\" y=\"128\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">試行10回</text>\n<text x=\"295\" y=\"128\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">試行100万回</text>\n<text x=\"170\" y=\"132\" fill=\"#e8eaf0\" font-size=\"8.5\" text-anchor=\"middle\" font-weight=\"600\" opacity=\"0\"> </text>\n</svg>", "terms": [["モンテカルロ法", "乱数を使った大量のシミュレーションで、近似的に答えを求める方法"], ["近似", "正確な値そのものではないが、それに十分近い値"]], "think": "なぜ『乱数を大量に使う』だけで答えに近づけるのかがカギ。1回や10回のランダムな試行では結果はバラつくが、大数の法則(既に学んだ、試行回数を増やすほど実際の割合が本来の確率に近づいていくという法則)により、試行の回数を100万回、1000万回と増やしていくほど、シミュレーションの結果は本当の答えにどんどん近づいていく。数式で一発で解く代わりに、乱数を使った試行を大量に積み重ねることで、答えを近似的に求めるのがモンテカルロ法の考え方。", "vs": "最小二乗法や交差検証は、手元にある実際のデータを使って計算や検証をする方法。モンテカルロ法は、乱数を使って人工的に大量の試行を作り出し、その結果から答えを見積もる点が違う。", "why_asked": "世の中には、数式を使って手で正確に解くにはあまりに複雑すぎる問題がたくさんある。そうした問題でも、乱数を使ってコンピュータに大量に試させることで、実用的な精度の答えを得られる、という発想を知らないと、複雑な問題は手も足も出ないと思い込んでしまう。", "usecase": "複雑な確率の計算、金融商品のリスクの見積もり、物理シミュレーションなど、数式で正確に解くのが難しいさまざまな分野で、答えの近似値を得るために使われる。", "opt": ["正解。乱数を使った大量のシミュレーションを行い、その結果から近似的に答えを求める方法がモンテカルロ法。", "最小二乗法は、手元にあるデータに対して誤差の2乗の合計が最小になるように式を決める方法。乱数を使ったシミュレーションではない。", "交差検証は、手元にあるデータの分け方を変えながらモデルの性能を確かめる方法。乱数で近似的に答えを求めるモンテカルロ法とは目的が異なる。", "ベイズ更新は、新しい証拠が入るたびに確率を計算し直す考え方。乱数を大量に使ったシミュレーションで答えを近似するモンテカルロ法とは別の方法。"]}'),

  ('stats20-q08', '確率過程とシミュレーション',
   '1辺2の正方形(面積4)の中に、半径1の円(面積π)がぴったり収まっている。この正方形の中にランダムな点を20個打ったら、16個が円の内側に入った。この「円の中に入った割合」から円周率を推定した値はどれ？',
   NULL::text,
   '["約3.2（16÷20×4）", "約0.8（16÷20）", "約1.25（20÷16）", "約4（正方形の面積をそのまま使う）"]',
   0, '[0]', 'single',
   '{"asked": "正方形の中に打った点のうち、円の内側に入った割合から円周率を推定する計算。", "point": "円の中に入った点の割合×4が、円周率πの推定値になる(正方形の面積4・円の面積π、その比がπ/4だから)。", "kid": "正方形の中にでたらめに点をたくさん打つと、円の内側に入る点の割合は、円の面積が正方形の面積のどれくらいかという比率(π/4)に近づいていく。この割合から逆算すると、円周率の近似値が求まる。", "eg": "的当てゲームで、正方形の壁に目をつぶって的をたくさん投げると、円の中に刺さった割合が、円の面積が壁全体に占める割合に近づいていく、というイメージ。", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\">\n<text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">点の入り方の割合からπを推定する</text>\n<rect x=\"105\" y=\"24\" width=\"90\" height=\"90\" fill=\"none\" stroke=\"#8892a4\" stroke-width=\"1.3\"/>\n<circle cx=\"150\" cy=\"69\" r=\"45\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.3\"/>\n<circle cx=\"128\" cy=\"45\" r=\"2.5\" fill=\"#3b82f6\"/>\n<circle cx=\"160\" cy=\"55\" r=\"2.5\" fill=\"#3b82f6\"/>\n<circle cx=\"170\" cy=\"90\" r=\"2.5\" fill=\"#3b82f6\"/>\n<circle cx=\"140\" cy=\"95\" r=\"2.5\" fill=\"#3b82f6\"/>\n<circle cx=\"150\" cy=\"70\" r=\"2.5\" fill=\"#3b82f6\"/>\n<circle cx=\"112\" cy=\"30\" r=\"2.5\" fill=\"#c47070\"/>\n<circle cx=\"188\" cy=\"32\" r=\"2.5\" fill=\"#c47070\"/>\n<circle cx=\"190\" cy=\"105\" r=\"2.5\" fill=\"#c47070\"/>\n<circle cx=\"113\" cy=\"105\" r=\"2.5\" fill=\"#c47070\"/>\n<text x=\"240\" y=\"45\" fill=\"#3b82f6\" font-size=\"8.5\" text-anchor=\"start\">円の中</text>\n<text x=\"240\" y=\"60\" fill=\"#c47070\" font-size=\"8.5\" text-anchor=\"start\">円の外</text>\n<text x=\"170\" y=\"132\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">円の中に入った割合 × 4 ≈ π</text>\n</svg>", "terms": [["モンテカルロ法", "乱数を使った大量のシミュレーションで近似的に答えを求める方法"], ["面積比", "円の面積を正方形の面積で割った値。ここではπ/4にあたる"]], "calc": "正方形の面積     2×2 = 4\n円の面積       半径1の円なのでπ×1² = π\n円÷正方形の面積   π÷4 ← この比率に、点の入る割合が近づいていく\n\n点20個のうち円の中16個\n割合         16÷20 = 0.8\nπの推定値      0.8 × 4 = 3.2 ← 0.8はπ÷4の近似なので、4を掛け戻すとπに近づく", "vs": "点の割合がそのまま円周率になるわけではない。割合は『円の面積÷正方形の面積』つまりπ÷4に近づくので、割合に4を掛け戻して初めてπの近似値になる。", "why_asked": "モンテカルロ法という言葉だけを覚えても、実際に何をどう数えて答えを出すのかがイメージできないと使えない。円周率の推定は、乱数から答えを近似する仕組みを具体的に体験できる定番の例。", "usecase": "複雑な図形の面積や体積を数式で正確に求めるのが難しいとき、同じように点をランダムに打って割合を数える方法で、近似値を求めることができる。", "think": "なぜ点の割合が円周率につながるのかがカギ。正方形の面積は4、その中にぴったり収まる円の面積はπ。もし正方形の中にでたらめに大量の点を打てば、それぞれの点が円の中に入るかどうかは、円の面積が正方形の面積に占める割合(π÷4)と同じ確率で決まる。だから点をたくさん打って『円の中に入った割合』を実際に数えれば、その割合はπ÷4に近づいていく。あとはこの割合に4を掛け戻せば、円周率πの近似値が得られる。点の数が多いほど、この近似はより正確な値に近づく(前問で見た、試行回数を増やすほど答えに近づくという考え方と同じ)。", "opt": ["正解。円の中に入った点の割合16÷20=0.8はπ÷4に近づくので、4を掛け戻すと0.8×4=3.2がπの推定値になる。", "16÷20=0.8は円の中に入った点の割合そのもの。これはπ÷4に近づく値であり、πの推定値にするには4を掛け戻す必要がある。", "20÷16は点の総数を円の中の点数で割ったもので、この問題で求めたい『割合に4を掛け戻す』計算とは違う式になっている。", "正方形の面積4は、点を1つも打たなくても最初から分かっている値。点の割合を反映していないので、円周率の推定値にはならない。"]}'),

  ('stats20-q09', '確率過程とシミュレーション',
   '以前の学習で「MCMC(マルコフ連鎖モンテカルロ法)」という手法が、複雑な事後分布の形を近似するために使われることを見た。ここまで学んだ「マルコフ連鎖」と「モンテカルロ法」という2つの言葉を踏まえると、MCMCはどんな組み合わせの手法だと言える？',
   NULL::text,
   '["直前の値から次を確率的に生成し(マルコフ連鎖)、大量に試しの値を作って(モンテカルロ法)分布を近似する手法", "決まった間隔でいつも規則正しく試しの値を生成する(ポアソン過程)やり方で、事後分布の形を正確に計算し尽くす手法", "手元の実際のデータだけを何度も並べ替えて、統計量のばらつきを見積もるリサンプリングの手法", "事前分布と事後分布が同じ種類の分布のままになる、数式の計算だけでいつも正確に解けてしまう手法"]',
   0, '[0]', 'single',
   '{"asked": "MCMCという名前が、マルコフ連鎖とモンテカルロ法という2つの手法をどう組み合わせたものか。", "point": "MCMCは名前どおり、マルコフ連鎖(直前の値から次を決める)とモンテカルロ法(大量に試して近似する)を組み合わせた手法。", "kid": "MCMCという名前は、実は『マルコフ連鎖』＋『モンテカルロ法』という、ここまで学んだ2つの言葉をそのままくっつけたもの。直前の試しの値を手がかりに次の値を作っていく(マルコフ連鎖の部分)やり方で、大量の試しの値を生み出し(モンテカルロ法の部分)、その集まりから複雑な分布の形を近似する。", "eg": "前回の値の近くを少しずつ手探りで進みながら、無数の点を打っていくようなもの。1回1回の値は直前の値をヒントに決まる(マルコフ連鎖)し、それを何万回も繰り返して分布の形を浮かび上がらせる(モンテカルロ法)。", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\">\n<text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">MCMCは2つの手法の組み合わせ</text>\n<rect x=\"24\" y=\"45\" width=\"110\" height=\"40\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.3\"/>\n<text x=\"79\" y=\"63\" fill=\"#e8eaf0\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"600\">マルコフ連鎖</text>\n<text x=\"79\" y=\"77\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">直前の値から次を決める</text>\n<text x=\"150\" y=\"70\" fill=\"#e8eaf0\" font-size=\"13\" text-anchor=\"middle\">+</text>\n<rect x=\"166\" y=\"45\" width=\"110\" height=\"40\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.3\"/>\n<text x=\"221\" y=\"63\" fill=\"#e8eaf0\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"600\">モンテカルロ法</text>\n<text x=\"221\" y=\"77\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">大量に試して近似する</text>\n<line x1=\"170\" y1=\"90\" x2=\"170\" y2=\"104\" stroke=\"#8892a4\" stroke-width=\"1.3\"/>\n<polygon points=\"170,108 165,100 175,100\" fill=\"#8892a4\"/>\n<rect x=\"60\" y=\"110\" width=\"220\" height=\"24\" fill=\"#3b82f6\" opacity=\"0.5\"/>\n<text x=\"170\" y=\"126\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">MCMC(マルコフ連鎖モンテカルロ法)</text>\n</svg>", "terms": [["MCMC", "マルコフ連鎖モンテカルロ法。直前の値から次の値を確率的に作り、大量に集めて分布を近似する手法"], ["マルコフ連鎖", "直前の状態だけで次が確率的に決まっていく現象の連なり"]], "think": "なぜマルコフ連鎖とモンテカルロ法を組み合わせる必要があるのかがカギ。モンテカルロ法だけでは、乱数から試しの値を大量に作ることはできても、複雑な形の分布(事後分布)に沿うように値を作るのは難しい。そこでマルコフ連鎖の考え方を使い、『直前の試しの値の近くを手がかりに、次の値を確率的に決めていく』という仕組みを組み込むと、値が自然と分布の形の濃いところに集まりやすくなる。この、直前の値をヒントに次を決める仕組み(マルコフ連鎖)と、大量に試して近似する仕組み(モンテカルロ法)を合わせたものが、MCMCの正体になる。", "vs": "普通のモンテカルロ法は、毎回の試しの値をそれぞれ独立に(前の値と無関係に)乱数で作ることが多い。MCMCは、次の試しの値を作るときに直前の値を手がかりにする点が違い、そこにマルコフ連鎖の考え方が加わっている。", "why_asked": "『MCMC』という略語だけを丸暗記していても、なぜその名前なのかが分からないと応用が利かない。マルコフ連鎖とモンテカルロ法という基礎を学んだいま、名前の意味から仕組みを理解し直すことができる。", "usecase": "複雑なベイズ統計のモデルで、数式では解けない事後分布の形を近似的に求めるときに、実際の統計ソフトの中でMCMCが使われている。", "opt": ["正解。直前の試しの値から次を確率的に決めるマルコフ連鎖のやり方で、大量の試しの値を作るモンテカルロ法を実行し、事後分布の形を近似する。これがMCMCの名前の由来。", "ポアソン過程は『一定の割合でランダムに出来事が起きる』現象を扱うモデルであり、決まった間隔で規則正しく値を作るものでもなければ、MCMCの組み合わせにも含まれない。", "リサンプリングは手元の実際のデータを並べ替えて使う方法。MCMCは乱数を使って新しい試しの値を次々に生成する方法であり、仕組みが異なる。", "共役事前分布は数式だけで事後分布を正確に解ける、特別で都合の良い組み合わせのこと。数式で解けない場合に近似で乗り切るMCMCとは逆の状況で使う言葉。"]}'),

  ('stats20-q10', '確率過程とシミュレーション',
   '確率過程とモンテカルロ法の考え方は、実務のさまざまな場面で使われている。次の組み合わせのうち、最も適切なのはどれ？',
   NULL::text,
   '["窓口や電話の待ち行列の混雑具合を見積もるにはポアソン過程、保険や金融でリスクを見積もるには大量のシナリオを試すモンテカルロ法が使われる", "窓口や電話の待ち行列の混雑具合を見積もるにはモンテカルロ法、保険や金融でリスクを見積もるには決まった間隔で起きる現象を扱うポアソン過程が使われる", "待ち行列の混雑具合もリスクの見積もりも、どちらも数式だけで正確に、乱数を使わずに解くことができる", "確率過程やモンテカルロ法は理論上の話にとどまり、実際の業務で使われることはほとんどない"]',
   0, '[0]', 'single',
   '{"asked": "確率過程とモンテカルロ法という2つの考え方が、実務のどんな場面でそれぞれ使われているか。", "point": "『タイミングがランダムに起きる現象の混雑』はポアソン過程、『数式で解けない複雑な未来のシナリオを大量に試す』はモンテカルロ法、が実務での使い分けの目安。", "kid": "ポアソン過程は『ランダムに起きる出来事のタイミング』を扱うのが得意なので、窓口や電話の待ち行列の混雑具合の予測に向いている。モンテカルロ法は『複雑すぎて数式で解けない問題』を大量のシミュレーションで近似するのが得意なので、将来のリスクの見積もりのように、いろいろな未来のシナリオを大量に試したい場面に向いている。", "eg": "銀行が『窓口を何台用意すれば、お客さんを待たせすぎないか』を考えるときはポアソン過程の考え方が土台になる。保険会社が『来年、大きな災害でどれくらいの支払いが発生しそうか』を見積もるときは、いろいろな災害シナリオをコンピュータの中で何万通りも試すモンテカルロ法が使われる。", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\">\n<text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">対象に合わせて使う道具が変わる</text>\n<rect x=\"20\" y=\"35\" width=\"130\" height=\"34\" fill=\"#2a2f3f\"/>\n<text x=\"85\" y=\"56\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">窓口の待ち行列</text>\n<line x1=\"150\" y1=\"52\" x2=\"180\" y2=\"52\" stroke=\"#8892a4\" stroke-width=\"1.3\"/>\n<polygon points=\"180,52 172,48 172,56\" fill=\"#8892a4\"/>\n<rect x=\"188\" y=\"35\" width=\"130\" height=\"34\" fill=\"#3b82f6\" opacity=\"0.55\"/>\n<text x=\"253\" y=\"56\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">ポアソン過程</text>\n<rect x=\"20\" y=\"88\" width=\"130\" height=\"34\" fill=\"#2a2f3f\"/>\n<text x=\"85\" y=\"105\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">保険・金融の</text>\n<text x=\"85\" y=\"117\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">リスク評価</text>\n<line x1=\"150\" y1=\"105\" x2=\"180\" y2=\"105\" stroke=\"#8892a4\" stroke-width=\"1.3\"/>\n<polygon points=\"180,105 172,101 172,109\" fill=\"#8892a4\"/>\n<rect x=\"188\" y=\"88\" width=\"130\" height=\"34\" fill=\"#c9a04a\" opacity=\"0.55\"/>\n<text x=\"253\" y=\"109\" fill=\"#141720\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">モンテカルロ法</text>\n</svg>", "terms": [["待ち行列", "窓口や電話などで、客や処理が並んで順番待ちする状況。ポアソン過程などを使って混雑具合を見積もる"], ["リスク評価", "将来起こりうる損失や被害の大きさを、確率を使って見積もること"]], "vs": "どちらも『確率過程・シミュレーション』という同じ大きな枠組みに属するが、ポアソン過程は出来事の発生タイミングそのものをモデル化する道具、モンテカルロ法は複雑な問題を乱数で近似的に解く計算のやり方、という役割の違いがある。", "why_asked": "確率過程・モンテカルロ法という言葉を、ただの数学の理論として覚えるだけでは終わらせず、待ち行列やリスク評価という具体的な実務のどこで役立っているかまで理解しておくと、このドリルで学んだ内容が実感を伴って身につく。", "usecase": "コールセンターの必要な人員数の見積もり、工場の機械が壊れるまでの時間の予測、金融商品や保険の将来のリスク評価、複雑なシステムのトラブル発生確率の予測など、確率過程とモンテカルロ法は現代のさまざまな意思決定の裏側で使われている。", "think": "なぜ待ち行列にはポアソン過程、リスク評価にはモンテカルロ法が向いているのかがカギ。窓口の混雑は『お客さんがランダムなタイミングで、しかし平均的なペースは分かった状態で訪れる』という、まさにポアソン過程がそのまま当てはまる状況になっている。一方、将来のリスクの見積もりは、災害の規模・発生時期・被害額など、いくつもの不確かな要素が絡み合っていて、数式1本できれいに解くのが難しい。そこで、それぞれの不確かな要素にありうる値をランダムに割り振ったシナリオを何万通りも作り(モンテカルロ法)、その結果の分布から『どれくらいの確率で、どれくらいの被害になりそうか』を近似的に見積もる。扱う対象の性質(タイミングの発生か、複雑な要素の組み合わせか)によって、向いている道具が分かれる。", "opt": ["正解。ランダムなタイミングで起きる出来事の混雑具合を扱うのが得意なポアソン過程は待ち行列の見積もりに、数式で解けない複雑な問題を大量のシミュレーションで近似するのが得意なモンテカルロ法はリスク評価に向いている。", "ポアソン過程は『決まった間隔で起きる現象』を扱う手法ではなく、ランダムなタイミングで起きる現象を扱う手法。組み合わせが入れ替わっているうえ、ポアソン過程の説明そのものも誤っている。", "待ち行列の混雑もリスクの見積もりも、不確かな要素が絡み合っていて数式だけで正確に解くのは難しいことが多い。だからこそ乱数を使ったシミュレーションが役立っている。", "コールセンターの人員配置や保険のリスク評価など、確率過程やモンテカルロ法は実際の業務の意思決定に日常的に活用されている。"]}')


) AS v(source_ref, category_name, question_text, code, options,
       correct_index, correct_indices, question_type, explanation_data)
  ON c.name = v.category_name AND s.slug = 'stats-basics'
ON CONFLICT (subject_id, source_ref) DO NOTHING;

COMMIT;
